1	//! Notes filesystem: folder tree, front-matter parsing, ordering, system folders.
2	//!
3	//! Split into focused submodules. This hub holds filesystem root/path
4	//! resolution, then re-exports each submodule so the crate-root notes::* surface
5	//! is unchanged.
6	
7	use std::{
8	    fs,
9	    path::{Component, Path, PathBuf},
10	};
11	
12	use crate::ports::notes::{
13	    NoteBodyCrypto, NoteClock, NoteDocumentCodec, NoteIdGenerator, NoteStorageEntryKind,
14	    NotesRepository,
15	};
16	use crate::{
17	    ensure_profiles_state, find_profile, FolderNode, NoteEntry, NoteFileNameFormat,
18	    NoteFrontMatter, OrderFile,
19	};
20	
21	mod front_matter;
22	mod naming;
23	mod tree;
24	
25	pub(crate) use front_matter::*;
26	pub(crate) use naming::*;
27	pub(crate) use tree::*;
28	
29	// ── Constants ──────────────────────────────────────────────────────────────────
30	
31	pub(crate) const ORDER_FILE: &str = ".notes-order.json";
32	pub(crate) const FEED_FOLDER: &str = "Feed";
33	pub(crate) const ARCHIEVE_FOLDER: &str = "Archieve";
34	const LEGACY_UNSORTED_FOLDER: &str = "Unsorted";
35	pub(crate) const RECORDINGS_STORAGE_FOLDER: &str = "Recordings";
36	pub(crate) const ATTACHMENTS_STORAGE_FOLDER: &str = "Attachments";
37	pub(crate) const LEGACY_RECORDINGS_FOLDER: &str = "_Recordings";
38	
39	const VISIBLE_SYSTEM_FOLDERS: [&str; 2] = [FEED_FOLDER, ARCHIEVE_FOLDER];
40	const REQUIRED_SYSTEM_FOLDERS: [&str; 4] = [
41	    FEED_FOLDER,
42	    ARCHIEVE_FOLDER,
43	    ATTACHMENTS_STORAGE_FOLDER,
44	    RECORDINGS_STORAGE_FOLDER,
45	];
46	pub(crate) const PROTECTED_SYSTEM_FOLDERS: [&str; 6] = [
47	    FEED_FOLDER,
48	    ARCHIEVE_FOLDER,
49	    LEGACY_UNSORTED_FOLDER,
50	    ATTACHMENTS_STORAGE_FOLDER,
51	    RECORDINGS_STORAGE_FOLDER,
52	    LEGACY_RECORDINGS_FOLDER,
53	];
54	const HIDDEN_ROOT_FOLDERS: [&str; 3] = [
55	    ATTACHMENTS_STORAGE_FOLDER,
56	    RECORDINGS_STORAGE_FOLDER,
57	    LEGACY_RECORDINGS_FOLDER,
58	];
59	
60	// ── Root resolution ────────────────────────────────────────────────────────────
61	
62	/// Resolve the active profile's notes root, creating the directory if needed.
63	pub(crate) fn notes_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
64	    let root = match ensure_profiles_state(app) {
65	        Ok(state) => {
66	            let active = find_profile(&state, &state.active_profile_id)
67	                .or_else(|| state.profiles.first())
68	                .ok_or_else(|| "No profiles configured.".to_string())?;
69	            PathBuf::from(&active.notes_root)
70	        }
71	        Err(_) => crate::legacy_notes_root(app)?,
72	    };
73	    if !root.exists() {
74	        fs::create_dir_all(&root).map_err(|err| err.to_string())?;
75	    }
76	    Ok(root)
77	}
78	
79	/// Notes root with system folders guaranteed to exist.
80	pub(crate) fn ensured_notes_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
81	    let root = notes_root(app)?;
82	    ensure_system_folders(&root)?;
83	    Ok(root)
84	}
85	
86	// ── Path helpers ───────────────────────────────────────────────────────────────
87	
88	/// Reject absolute paths and parent-dir traversals.
89	pub(crate) fn sanitize_relative(path: &str) -> Result<PathBuf, String> {
90	    if path.is_empty() {
91	        return Ok(PathBuf::new());
92	    }
93	    let candidate = Path::new(path);
94	    if candidate.is_absolute() {
95	        return Err("Absolute paths are not allowed.".to_string());
96	    }
97	    for component in candidate.components() {
98	        match component {
99	            Component::ParentDir | Component::RootDir | Component::Prefix(_) => {
100	                return Err("Invalid path traversal.".to_string())
101	            }
102	            _ => {}
103	        }
104	    }
105	    Ok(candidate.to_path_buf())
106	}
107	
108	/// Join a sanitized relative path onto the notes root.
109	pub(crate) fn resolve_path(app: &tauri::AppHandle, rel: &str) -> Result<PathBuf, String> {
110	    let root = notes_root(app)?;
111	    let rel_path = sanitize_relative(rel)?;
112	    Ok(root.join(rel_path))
113	}
114	
115	/// Strip the notes root prefix, returning a forward-slash relative path.
116	pub(crate) fn strip_root(root: &Path, path: &Path) -> String {
117	    path.strip_prefix(root)
118	        .unwrap_or(path)
