1	//! Folder tree construction, system folders, legacy migration, and order files.
2	
3	use std::{
4	    collections::HashMap,
5	    fs,
6	    path::{Path, PathBuf},
7	};
8	
9	use super::*;
10	
11	// ── File collection ────────────────────────────────────────────────────────────
12	
13	/// Recursively collect all `.md` files, skipping hidden and storage folders.
14	pub(crate) fn collect_markdown_note_files(
15	    root: &Path,
16	    dir: &Path,
17	    files: &mut Vec<PathBuf>,
18	) -> Result<(), String> {
19	    for entry in fs::read_dir(dir).map_err(|error| error.to_string())? {
20	        let entry = entry.map_err(|error| error.to_string())?;
21	        let path = entry.path();
22	        let name = entry.file_name().to_string_lossy().to_string();
23	        if name == ORDER_FILE {
24	            continue;
25	        }
26	        let metadata = entry.metadata().map_err(|error| error.to_string())?;
27	        if metadata.is_dir() {
28	            if name.starts_with('.') {
29	                continue;
30	            }
31	            if dir == root {
32	                if HIDDEN_ROOT_FOLDERS.iter().any(|hidden| *hidden == name) {
33	                    continue;
34	                }
35	            }
36	            collect_markdown_note_files(root, &path, files)?;
37	            continue;
38	        }
39	        if metadata.is_file() && path.extension().and_then(|value| value.to_str()) == Some("md") {
40	            files.push(path);
41	        }
42	    }
43	    Ok(())
44	}
45	
46	// ── Ordering & sorting ─────────────────────────────────────────────────────────
47	
48	/// Sort names according to a persisted order list, alphabetical fallback.
49	pub(crate) fn sort_by_order(mut names: Vec<String>, order: &[String]) -> Vec<String> {
50	    let mut index = HashMap::new();
51	    for (idx, name) in order.iter().enumerate() {
52	        index.insert(name, idx);
53	    }
54	    names.sort_by(|a, b| {
55	        let a_idx = index.get(a).copied().unwrap_or(usize::MAX);
56	        let b_idx = index.get(b).copied().unwrap_or(usize::MAX);
57	        a_idx
58	            .cmp(&b_idx)
59	            .then_with(|| a.to_lowercase().cmp(&b.to_lowercase()))
60	    });
61	    names
62	}
63	
64	// ── Folder classification ──────────────────────────────────────────────────────
65	
66	/// True if the folder name matches a protected system folder.
67	pub(crate) fn is_system_folder_name(name: &str) -> bool {
68	    PROTECTED_SYSTEM_FOLDERS
69	        .iter()
70	        .any(|folder| *folder == name)
71	}
72	
73	/// True if the folder should be hidden from the tree at root level.
74	pub(crate) fn is_hidden_root_folder_name(name: &str) -> bool {
75	    HIDDEN_ROOT_FOLDERS.iter().any(|folder| *folder == name)
76	}
77	
78	/// True if the path is the Feed folder.
79	pub(crate) fn is_feed_folder_path(root: &Path, path: &Path) -> bool {
80	    path == root.join(FEED_FOLDER)
81	}
82	
83	// ── Legacy migration ───────────────────────────────────────────────────────────
84	
85	fn migrate_legacy_folder_name(root: &Path, from_name: &str, to_name: &str) -> Result<(), String> {
86	    let from = root.join(from_name);
87	    if !from.exists() {
88	        return Ok(());
89	    }
90	    let to = root.join(to_name);
91	    if !to.exists() {
92	        fs::rename(&from, &to).map_err(|err| err.to_string())?;
93	        return Ok(());
94	    }
95	    for entry in fs::read_dir(&from).map_err(|err| err.to_string())? {
96	        let entry = entry.map_err(|err| err.to_string())?;
97	        let source = entry.path();
98	        let target = to.join(entry.file_name());
99	        if target.exists() {
100	            continue;
101	        }
102	        fs::rename(&source, &target).map_err(|err| err.to_string())?;
