207	    fn native_capabilities(&self) -> Result<Self::NativeCapabilities, String> {
208	        #[cfg(target_os = "ios")]
209	        {
210	            let (recording, started_ms) = crate::ios_native_recorder_state()
211	                .lock()
212	                .map(|guard| {
213	                    let Some(state) = guard.as_ref() else {
214	                        return (false, None);
215	                    };
216	                    let recorder = state.recorder_ptr as *mut Object;
217	                    let resumed = crate::ios_ensure_recorder_active(recorder);
218	                    (resumed, state.started_ms)
219	                })
220	                .unwrap_or((false, None));
221	            return Ok(NativeRecorderCapabilities {
222	                supported: true,
223	                recording,
224	                started_ms,
225	            });
226	        }
227	
228	        #[cfg(not(target_os = "ios"))]
229	        {
230	            Ok(NativeRecorderCapabilities {
231	                supported: false,
232	                recording: false,
233	                started_ms: None,
