347	    fn queue_cloud(&self, args: Self::CloudQueueArgs) -> Result<Self::QueueResult, String> {
348	        let app_data = crate::app_data_dir(&self.app)?;
349	        let app_config = crate::load_app_config(&app_data);
350	
351	        let api_key = args
352	            .assembly_api_key
353	            .as_deref()
354	            .filter(|s| !s.is_empty())
355	            .unwrap_or(app_config.assemblyai_api_key.as_str())
356	            .trim();
357	
358	        if api_key.is_empty() {
359	            return Err("AssemblyAI API key is required.".to_string());
360	        }
361	
362	        let root = crate::ensured_notes_root(&self.app)?;
363	        let recordings = collect_recording_notes(&root)?;
364	        let active_recordings = active_transcription_note_paths();
365	        let mut scanned = 0usize;
366	        let mut skipped = 0usize;
367	        let mut candidates = Vec::new();
368	
369	        for recording in recordings {
370	            scanned += 1;
371	            if !recording.audio_path.exists() {
372	                let _ = update_recording_note_status(
373	                    &recording.note_path,
374	                    RECORDING_STATUS_FAILED,
375	                    Some("Audio file is missing.".to_string()),
376	                    None,
377	                    None,
378	                );
379	                skipped += 1;
380	                continue;
381	            }
382	
383	            let status = recording.status.as_str();
384	            let is_active_recording = active_recordings.contains(&recording.note_rel);
385	            if status == RECORDING_STATUS_COMPLETED {
386	                skipped += 1;
387	                continue;
388	            }
389	            if matches!(
390	                status,
391	                crate::RECORDING_STATUS_QUEUED | RECORDING_STATUS_PROCESSING
392	            ) && is_active_recording
393	            {
394	                skipped += 1;
395	                continue;
396	            }
397	
398	            update_recording_note_status(
399	                &recording.note_path,
400	                crate::RECORDING_STATUS_QUEUED,
401	                None,
402	                None,
403	                None,
404	            )?;
405	            candidates.push(QueuedTranscriptionJob {
406	                note_rel: recording.note_rel,
407	                note_path: recording.note_path,
408	                audio_path: recording.audio_path,
409	                method: TranscriptionMethod::AssemblyAi {
410	                    api_key: api_key.to_string(),
411	                },
412	            });
413	        }
414	
415	        let queued = {
416	            let queue = transcription_queue_state();
417	            let mut state = queue.lock().expect("transcription queue poisoned");
418	            let mut added = 0usize;
419	            for job in candidates {
420	                if state.known_recordings.contains(&job.note_rel) {
421	                    continue;
422	                }
423	                state.known_recordings.insert(job.note_rel.clone());
424	                state.pending.push_back(job);
425	                added += 1;
426	            }
427	            added
428	        };
429	
430	        spawn_transcription_worker_if_needed();
431	        let in_flight = recording_queue_snapshot().in_flight;
432	
433	        Ok(RecordingTranscriptionQueueResult {
434	            scanned,
435	            queued,
436	            skipped,
437	            in_flight,
438	        })
439	    }
