564	/// Collect note paths that are currently queued or being transcribed.
565	pub(crate) fn active_transcription_note_paths() -> HashSet<String> {
566	    let queue = transcription_queue_state();
567	    let state = queue.lock().expect("transcription queue poisoned");
568	    let mut active = HashSet::with_capacity(state.pending.len() + 1);
569	    if let Some(current) = &state.current_recording {
570	        active.insert(current.clone());
571	    }
572	    active.extend(state.pending.iter().map(|job| job.note_rel.clone()));
573	    active
574	}
