578	    let queue = transcription_queue_state();
579	    let state = queue.lock().expect("transcription queue poisoned");
580	    let pending = state
581	        .pending
582	        .iter()
583	        .map(|job| job.note_rel.clone())
584	        .collect::<Vec<_>>();
585	    RecordingQueueSnapshot {
586	        running: state.running,
587	        current_recording: state.current_recording.clone(),
588	        in_flight: pending.len() + usize::from(state.running),
589	        pending,
590	    }
591	}
