595	/// Map a MIME type to a file extension (defaults to "webm").
596	pub(crate) fn audio_extension_from_mime(mime_type: Option<&str>) -> &'static str {
597	    let Some(raw) = mime_type else {
598	        return "webm";
599	    };
600	    let normalized = raw.to_lowercase();
601	    if normalized.contains("mp4") || normalized.contains("aac") {
602	        return "m4a";
603	    }
604	    if normalized.contains("mpeg") || normalized.contains("mp3") {
605	        return "mp3";
606	    }
607	    if normalized.contains("wav") {
608	        return "wav";
609	    }
610	    if normalized.contains("ogg") {
611	        return "ogg";
612	    }
613	    if normalized.contains("flac") {
614	        return "flac";
615	    }
616	    "webm"
617	}
618	
619	/// Infer MIME type from an audio file's extension.
620	pub(crate) fn audio_mime_from_path(path: &Path) -> &'static str {
621	    let ext = path
622	        .extension()
623	        .and_then(|value| value.to_str())
624	        .unwrap_or("")
625	        .to_lowercase();
626	    match ext.as_str() {
627	        "m4a" => "audio/mp4",
628	        "mp3" => "audio/mpeg",
629	        "wav" => "audio/wav",
630	        "ogg" => "audio/ogg",
631	        "webm" => "audio/webm",
632	        "aac" => "audio/aac",
633	        "mp4" => "audio/mp4",
634	        "flac" => "audio/flac",
635	        _ => "application/octet-stream",
636	    }
637	}
