664	fn recording_info_from_note_meta(
665	    root: &Path,
666	    note_path: &Path,
667	    note_rel: &str,
668	    meta: &NoteFrontMatter,
669	) -> Option<RecordingNoteInfo> {
670	    if meta.note_type.as_deref() != Some(RECORDING_FRONTMATTER_TYPE) {
671	        return None;
672	    }
673	    let audio_rel = meta.recording_audio_path.as_ref()?.trim();
674	    if audio_rel.is_empty() {
675	        return None;
676	    }
677	    let audio_rel_path = sanitize_relative(audio_rel).ok()?;
678	    let audio_path = root.join(&audio_rel_path);
679	    if !is_recording_audio_path_allowed(root, &audio_path) {
680	        return None;
681	    }
682	    let status = meta
683	        .transcription_status
684	        .as_deref()
685	        .unwrap_or(RECORDING_STATUS_PENDING)
686	        .to_string();
687	    Some(RecordingNoteInfo {
688	        note_rel: note_rel.to_string(),
689	        note_path: note_path.to_path_buf(),
690	        audio_rel: audio_rel_path.to_string_lossy().replace('\\', "/"),
691	        audio_path,
692	        status,
693	        error: meta.transcription_error.clone(),
694	        updated_ms: meta.transcription_updated_ms.or(meta.updated_ms),
695	    })
696	}
