698	/// Scan all markdown notes and extract recording metadata.
699	pub(crate) fn collect_recording_notes(root: &Path) -> Result<Vec<RecordingNoteInfo>, String> {
700	    let mut note_files = Vec::new();
701	    collect_markdown_note_files(root, root, &mut note_files)?;
702	    let mut recordings = Vec::new();
703	    for note_path in note_files {
704	        let raw = match fs::read_to_string(&note_path) {
705	            Ok(value) => value,
706	            Err(_) => continue,
707	        };
708	        let (meta, _) = parse_note_front_matter(&raw);
709	        let note_rel = strip_root(root, &note_path);
710	        if let Some(info) = recording_info_from_note_meta(root, &note_path, &note_rel, &meta) {
711	            recordings.push(info);
712	        }
713	    }
714	    Ok(recordings)
715	}
716	
717	/// Update a recording note's transcription status and body on disk.
718	pub(crate) fn update_recording_note_status(
719	    note_path: &Path,
720	    status: &str,
721	    error: Option<String>,
722	    transcript_id: Option<String>,
723	    transcript_text: Option<&str>,
724	) -> Result<(), String> {
725	    let raw = fs::read_to_string(note_path).map_err(|issue| issue.to_string())?;
726	    let (mut meta, _) = parse_note_front_matter(&raw);
727	    if meta.id.is_none() {
728	        meta.id = Some(generate_note_id());
729	    }
730	    let now = now_ms();
731	    if meta.created_ms.is_none() {
732	        meta.created_ms = now;
733	    }
734	    meta.updated_ms = now.or(meta.updated_ms);
735	    meta.note_type = Some(RECORDING_FRONTMATTER_TYPE.to_string());
736	    meta.transcription_status = Some(status.to_string());
737	    meta.transcription_error = error.clone();
738	    meta.transcription_updated_ms = now.or(meta.transcription_updated_ms);
739	    meta.transcription_id = transcript_id;
740	    let next_body = recording_note_body(status, transcript_text);
741	    write_note_with_front_matter(note_path, &meta, &next_body)
742	}
743	
744	// ── Worker ─────────────────────────────────────────────────────────────────────
745	
746	fn process_transcription_job(job: QueuedTranscriptionJob) {
747	    if let Err(error) = update_recording_note_status(
748	        &job.note_path,
749	        RECORDING_STATUS_PROCESSING,
750	        None,
751	        None,
752	        None,
753	    ) {
754	        eprintln!(
755	            "[recordings] failed to mark processing for {}: {}",
756	            job.note_rel, error
757	        );
758	    }
759	
760	    let result = match &job.method {
761	        TranscriptionMethod::LocalWhisper { model, app } => {
762	            // Provision the managed Python env on first use; subsequent jobs are
763	            // instant. Any setup failure surfaces as the note's transcription error.
764	            match crate::ensure_whisper_env(app) {
765	                Ok(python) => transcribe_audio_local_whisper(&job.audio_path, model, &python),
766	                Err(error) => Err(format!("Failed to set up local transcription: {error}")),
767	            }
768	        }
769	        TranscriptionMethod::AssemblyAi { api_key } => {
770	            let audio_bytes = match fs::read(&job.audio_path) {
771	                Ok(bytes) => bytes,
772	                Err(e) => {
773	                    let _ = update_recording_note_status(
774	                        &job.note_path,
775	                        RECORDING_STATUS_FAILED,
776	                        Some(e.to_string()),
777	                        None,
778	                        None,
779	                    );
780	                    eprintln!(
781	                        "[recordings] failed to read audio for {}: {}",
782	                        job.note_rel, e
783	                    );
784	                    return;
785	                }
786	            };
787	            transcribe_audio_bytes_with_assembly(audio_bytes, api_key)
788	        }
789	    };
790	
791	    match result {
792	        Ok((transcript, id_or_json)) => {
793	            // For local whisper, id_or_json is the full JSON with word timestamps.
794	            // Save word-level JSON alongside the audio file.
795	            if matches!(job.method, TranscriptionMethod::LocalWhisper { .. }) {
796	                if let Err(e) = save_word_level_json(&job.audio_path, &id_or_json) {
797	                    eprintln!(
798	                        "[recordings] failed to save word-level JSON for {}: {}",
799	                        job.note_rel, e
800	                    );
801	                }
802	            }
803	
804	            let transcript_id = match &job.method {
805	                TranscriptionMethod::AssemblyAi { .. } => Some(id_or_json),
806	                TranscriptionMethod::LocalWhisper { .. } => None,
807	            };
808	
809	            if let Err(error) = update_recording_note_status(
810	                &job.note_path,
811	                RECORDING_STATUS_COMPLETED,
812	                None,
813	                transcript_id,
814	                Some(&transcript),
815	            ) {
816	                eprintln!(
817	                    "[recordings] failed to write transcript for {}: {}",
818	                    job.note_rel, error
819	                );
820	            }
821	        }
822	        Err(error) => {
823	            let _ = update_recording_note_status(
824	                &job.note_path,
825	                RECORDING_STATUS_FAILED,
826	                Some(error.clone()),
827	                None,
828	                None,
829	            );
830	            eprintln!(
831	                "[recordings] transcription failed for {}: {}",
832	                job.note_rel, error
833	            );
834	        }
835	    }
836	}
837	
838	/// Start a background worker thread if jobs are queued and none is running.
839	pub(crate) fn spawn_transcription_worker_if_needed() {
840	    let should_spawn = {
841	        let queue = transcription_queue_state();
842	        let mut state = queue.lock().expect("transcription queue poisoned");
843	        if state.running || state.pending.is_empty() {
844	            false
845	        } else {
846	            state.running = true;
847	            true
848	        }
849	    };
850	    if !should_spawn {
851	        return;
852	    }
853	    thread::spawn(move || loop {
854	        let maybe_job = {
855	            let queue = transcription_queue_state();
856	            let mut state = queue.lock().expect("transcription queue poisoned");
857	            match state.pending.pop_front() {
858	                Some(job) => {
859	                    state.current_recording = Some(job.note_rel.clone());
860	                    Some(job)
861	                }
862	                None => {
863	                    state.running = false;
864	                    state.current_recording = None;
865	                    None
866	                }
867	            }
868	        };
869	        let Some(job) = maybe_job else {
870	            break;
871	        };
872	        process_transcription_job(job.clone());
873	        let queue = transcription_queue_state();
874	        let mut state = queue.lock().expect("transcription queue poisoned");
875	        state.known_recordings.remove(&job.note_rel);
876	        if state.current_recording.as_deref() == Some(job.note_rel.as_str()) {
877	            state.current_recording = None;
878	        }
879	    });
880	}
881	
882	// ── Queue helpers for local transcription ──────────────────────────────────────
883	
884	/// Queue all pending recordings for local whisper transcription (desktop only).
885	pub(crate) fn queue_recordings_for_local_transcription(
886	    app: &tauri::AppHandle,
887	    root: &Path,
888	    model: &str,
889	) -> Result<RecordingTranscriptionQueueResult, String> {
890	    let recordings = collect_recording_notes(root)?;
891	    let active_recordings = active_transcription_note_paths();
892	    let mut scanned = 0usize;
893	    let mut skipped = 0usize;
894	    let mut candidates = Vec::new();
895	
896	    for recording in recordings {
897	        scanned += 1;
898	        if !recording.audio_path.exists() {
899	            let _ = update_recording_note_status(
900	                &recording.note_path,
901	                RECORDING_STATUS_FAILED,
902	                Some("Audio file is missing.".to_string()),
903	                None,
904	                None,
905	            );
906	            skipped += 1;
907	            continue;
908	        }
909	
910	        let status = recording.status.as_str();
911	        let is_active = active_recordings.contains(&recording.note_rel);
912	
913	        if status == RECORDING_STATUS_COMPLETED {
914	            skipped += 1;
915	            continue;
916	        }
917	
918	        if matches!(
919	            status,
920	            crate::RECORDING_STATUS_QUEUED | RECORDING_STATUS_PROCESSING
921	        ) && is_active
922	        {
923	            skipped += 1;
924	            continue;
925	        }
926	
927	        update_recording_note_status(
928	            &recording.note_path,
929	            crate::RECORDING_STATUS_QUEUED,
930	            None,
931	            None,
932	            None,
933	        )?;
934	        candidates.push(QueuedTranscriptionJob {
935	            note_rel: recording.note_rel,
936	            note_path: recording.note_path,
937	            audio_path: recording.audio_path,
938	            method: TranscriptionMethod::LocalWhisper {
939	                model: model.to_string(),
940	                app: app.clone(),
941	            },
942	        });
943	    }
944	
945	    let queued = {
946	        let queue = transcription_queue_state();
947	        let mut state = queue.lock().expect("transcription queue poisoned");
948	        let mut added = 0usize;
949	        for job in candidates {
950	            if state.known_recordings.contains(&job.note_rel) {
951	                continue;
952	            }
953	            state.known_recordings.insert(job.note_rel.clone());
954	            state.pending.push_back(job);
955	            added += 1;
956	        }
957	        added
958	    };
959	
960	    spawn_transcription_worker_if_needed();
961	
962	    let in_flight = {
963	        let queue = transcription_queue_state();
964	        let state = queue.lock().expect("transcription queue poisoned");
965	        state.pending.len() + usize::from(state.running)
966	    };
967	
968	    Ok(RecordingTranscriptionQueueResult {
969	        scanned,
970	        queued,
971	        skipped,
972	        in_flight,
973	    })
974	}
975	
976	/// Reset a single recording's status and re-queue it for local transcription.
977	pub(crate) fn retrigger_single_transcription(
978	    app: &tauri::AppHandle,
979	    root: &Path,
980	    note_rel: &str,
981	    model: &str,
982	) -> Result<(), String> {
983	    let note_path = root.join(note_rel);
984	    if !note_path.exists() {
985	        return Err(format!("Note not found: {}", note_rel));
986	    }
987	    let raw = fs::read_to_string(&note_path).map_err(|e| e.to_string())?;
988	    let (meta, _) = parse_note_front_matter(&raw);
989	    let info = recording_info_from_note_meta(root, &note_path, note_rel, &meta)
990	        .ok_or_else(|| format!("Not a recording note: {}", note_rel))?;
991	
992	    if !info.audio_path.exists() {
993	        return Err("Audio file is missing.".to_string());
994	    }
995	
996	    // Reset status to queued
997	    update_recording_note_status(&note_path, crate::RECORDING_STATUS_QUEUED, None, None, None)?;
998	
999	    // Add to queue
1000	    {
1001	        let queue = transcription_queue_state();
1002	        let mut state = queue.lock().expect("transcription queue poisoned");
1003	        // Remove from known so it can be re-queued
1004	        state.known_recordings.remove(note_rel);
1005	        state.known_recordings.insert(note_rel.to_string());
1006	        state.pending.push_back(QueuedTranscriptionJob {
1007	            note_rel: note_rel.to_string(),
1008	            note_path,
1009	            audio_path: info.audio_path,
1010	            method: TranscriptionMethod::LocalWhisper {
1011	                model: model.to_string(),
1012	                app: app.clone(),
1013	            },
1014	        });
1015	    }
1016	
1017	    spawn_transcription_worker_if_needed();
1018	    Ok(())
1019	}
1020	
1021	// ── File allocation ────────────────────────────────────────────────────────────
1022	
1023	/// Default body for a newly created recording note (empty).
1024	pub(crate) fn recording_initial_body() -> String {
1025	    String::new()
1026	}
1027	
1028	/// Generate a unique filename for a recording note.
1029	pub(crate) fn recording_note_file_name(
1030	    folder: &Path,
1031	    timestamp_ms: i64,
1032	    note_id: &str,
1033	    file_name_format: NoteFileNameFormat,
1034	) -> Result<String, String> {
1035	    let fallback = format!("recording-{}", uuid_tail_without_timestamp_prefix(note_id));
1036	    allocate_note_file_name(
1037	        folder,
1038	        timestamp_ms,
1039	        note_id,
1040	        "",
1041	        &fallback,
1042	        file_name_format,
1043	    )
1044	}
1045	
1046	/// Allocate a unique audio file path inside the Recordings storage folder.
1047	pub(crate) fn recording_audio_file_path(root: &Path, extension: &str) -> Result<PathBuf, String> {
1048	    let storage = recording_storage_root(root);
1049	    fs::create_dir_all(&storage).map_err(|error| error.to_string())?;
1050	    for _ in 0..=512usize {
1051	        let candidate = storage.join(format!(
1052	            "{}-{}.{}",
1053	            AUDIO_FILE_NAME_PREFIX,
1054	            Uuid::now_v7(),
1055	            extension
1056	        ));
1057	        if !candidate.exists() {
1058	            return Ok(candidate);
1059	        }
1060	    }
1061	    Err("Failed to allocate recording audio filename.".to_string())
1062	}
1063	
1064	/// Resolve the target folder for a new recording, falling back to Feed.
1065	pub(crate) fn resolve_recording_target_folder(
1066	    app: &tauri::AppHandle,
1067	    requested: Option<&str>,
1068	) -> Result<(String, PathBuf), String> {
1069	    let root = notes_root(app)?;
1070	    let candidate = requested.unwrap_or("").trim();
1071	    if !candidate.is_empty() {
1072	        let path = resolve_path(app, candidate)?;
1073	        if path.exists() && path.is_dir() && !is_storage_folder_path(&root, &path) {
1074	            return Ok((strip_root(&root, &path), path));
1075	        }
1076	    }
1077	    let fallback = root.join(FEED_FOLDER);
1078	    Ok((FEED_FOLDER.to_string(), fallback))
1079	}
