//
//  WriteView.swift
//  Type
//
//  The blank page. You open the app and type directly. Swipe up to commit the
//  current note — it slides up and away — and a fresh blank page takes its place.
//  This is the one interaction carried over verbatim from the brief.
//

import SwiftUI

struct WriteView: View {
    @Environment(AppState.self) private var app
    @FocusState private var focused: Bool
    @State private var committing = false

    private let commitThreshold: CGFloat = 80

    var body: some View {
        @Bindable var app = app

        GeometryReader { geo in
            ZStack(alignment: .topLeading) {
                TextEditor(text: $app.draftText)
                    .font(.title3)
                    .lineSpacing(3)
                    .scrollContentBackground(.hidden)
                    .padding(.horizontal, 18)
                    .padding(.top, 12)
                    .focused($focused)
                    .offset(y: committing ? -geo.size.height : 0)
                    .opacity(committing ? 0 : 1)

                if app.draftText.isEmpty && !committing {
                    Text("Start typing…")
                        .font(.title3)
                        .foregroundStyle(.tertiary)
                        .padding(.horizontal, 23)
                        .padding(.top, 20)
                        .allowsHitTesting(false)
                }

                VStack {
                    Spacer()
                    if !app.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                        Label("Swipe up for a new note", systemImage: "chevron.up")
                            .font(.caption)
                            .foregroundStyle(.tertiary)
                            .frame(maxWidth: .infinity)
                            .padding(.bottom, 6)
                            .allowsHitTesting(false)
                    }
                }
            }
            .contentShape(Rectangle())
            .highPriorityGesture(
                DragGesture(minimumDistance: 24)
                    .onEnded { value in
                        if value.translation.height < -commitThreshold
                            && value.velocity.height < 0
                        {
                            commit()
                        }
                    }
            )
            .onTapGesture { focused = true }
        }
        .ignoresSafeArea(.keyboard, edges: .bottom)
        .onAppear { focused = true }
    }

    private func commit() {
        guard !app.draftText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        withAnimation(.easeIn(duration: 0.22)) { committing = true }
        Task {
            try? await Task.sleep(for: .milliseconds(240))
            app.commitDraft()
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) { committing = false }
            focused = true
        }
    }
}

