//
//  NotesStore.swift
//  Type
//
//  Filesystem engine for a single notes root. Layout-compatible with the Rust
//  backend so the same git repository round-trips between desktop and iOS.
//
//  All methods are `nonisolated` and synchronous so callers can run them off the
//  main actor (`await Task.detached { … }`) for large trees. Notes are small, so
//  Stage 1 calls them directly.
//
//  NOTE: At-rest encryption is intentionally NOT implemented here (it is a later
//  design item). Bodies are written as plaintext, which is compatible with a
//  desktop that also has encryption disabled (the default).
//

import Foundation

enum NotesStoreError: LocalizedError {
    case protectedFolder(String)
    case invalidName(String)
    case notFound(String)

    var errorDescription: String? {
        switch self {
        case .protectedFolder(let name): return "“\(name)” is a system folder and can't be changed."
        case .invalidName(let name): return "“\(name)” isn't a valid name."
        case .notFound(let path): return "Couldn't find “\(path)”."
        }
    }
}

struct NotesStore {
    let root: URL

    init(root: URL) { self.root = root }

    // MARK: Path helpers

    nonisolated func url(forRelative rel: String) -> URL {
        let trimmed = rel.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        guard !trimmed.isEmpty else { return root }
        var url = root
        for component in trimmed.split(separator: "/") {
            url.appendPathComponent(String(component))
        }
        return url
    }

    nonisolated func relative(of url: URL) -> String {
        let rootComponents = root.standardizedFileURL.pathComponents
        let urlComponents = url.standardizedFileURL.pathComponents
        guard urlComponents.count >= rootComponents.count,
            Array(urlComponents.prefix(rootComponents.count)) == rootComponents
        else {
            return url.path
        }
        return urlComponents.dropFirst(rootComponents.count).joined(separator: "/")
    }

    // MARK: System folders + legacy migration

//
//  RootView.swift
//  Type
//
//  Top-level tab composition. The app opens on Write (the blank page) per the
//  product brief; Browse and Settings are secondary. The Record tab is added in
//  Stage 3.
//

import SwiftUI

struct RootView: View {
    @Environment(AppState.self) private var app
    @Environment(\.scenePhase) private var scenePhase
    @State private var selection: Tab = .write

    enum Tab: Hashable { case write, record, browse, settings }

    var body: some View {
        TabView(selection: $selection) {
            WriteView()
                .tabItem { Label("Write", systemImage: "square.and.pencil") }
                .tag(Tab.write)

            RecordingView()
                .tabItem { Label("Record", systemImage: "mic") }
                .tag(Tab.record)

            BrowseView()
                .tabItem { Label("Browse", systemImage: "folder") }
                .tag(Tab.browse)

            SettingsView()
                .tabItem { Label("Settings", systemImage: "gearshape") }
                .tag(Tab.settings)
        }
        .onChange(of: scenePhase) { _, phase in
            // Persist the draft when the app goes to the background so nothing is
            // lost (the desktop does the same on visibility change).
            if phase != .active {
                app.commitDraft()
            }
        }
        .onChange(of: app.pendingRecordIntent) { _, pending in
            // A `type://record` deep link (home-screen widget) routes us to the
            // Record tab; RecordingView consumes the flag and auto-starts.
            if pending { selection = .record }
        }
        .overlay(alignment: .top) {
            if let error = app.loadError {
                Text(error)
                    .font(.footnote)
                    .padding(8)
                    .background(.red.opacity(0.9), in: Capsule())
                    .foregroundStyle(.white)
                    .padding(.top, 4)
                    .transition(.move(edge: .top))
                    .onTapGesture { app.loadError = nil }
            }
        }
    }
}

//
//  RecordWidgetBundle.swift
//  Type Record Widget   (widget extension target)
//
//  The extension's entry point. Bundles every surface: the static home-screen /
//  lock-screen widgets, the Control-Center control, and the recording Live
//  Activity.
//

import SwiftUI
import WidgetKit

@main
struct RecordWidgetBundle: WidgetBundle {
    var body: some Widget {
        RecordWidget()
        RecordControl()
        RecordingLiveActivity()
    }
}

