//
//  NotesStore.swift
//  Type
//
//  Filesystem engine for a single notes root. Layout-compatible with the Rust
//  backend so the same git repository round-trips between desktop and iOS.
//
//  All methods are `nonisolated` and synchronous so callers can run them off the
//  main actor (`await Task.detached { … }`) for large trees. Notes are small, so
//  Stage 1 calls them directly.
//
//  NOTE: At-rest encryption is intentionally NOT implemented here (it is a later
//  design item). Bodies are written as plaintext, which is compatible with a
//  desktop that also has encryption disabled (the default).
//

import Foundation

enum NotesStoreError: LocalizedError {
    case protectedFolder(String)
    case invalidName(String)
    case notFound(String)

    var errorDescription: String? {
        switch self {
        case .protectedFolder(let name): return "“\(name)” is a system folder and can't be changed."
        case .invalidName(let name): return "“\(name)” isn't a valid name."
        case .notFound(let path): return "Couldn't find “\(path)”."
        }
    }
}

struct NotesStore {
    let root: URL

    init(root: URL) { self.root = root }

    // MARK: Path helpers

    nonisolated func url(forRelative rel: String) -> URL {
        let trimmed = rel.trimmingCharacters(in: CharacterSet(charactersIn: "/"))
        guard !trimmed.isEmpty else { return root }
        var url = root
        for component in trimmed.split(separator: "/") {
            url.appendPathComponent(String(component))
        }
        return url
    }

    nonisolated func relative(of url: URL) -> String {
        let rootComponents = root.standardizedFileURL.pathComponents
        let urlComponents = url.standardizedFileURL.pathComponents
        guard urlComponents.count >= rootComponents.count,
            Array(urlComponents.prefix(rootComponents.count)) == rootComponents
        else {
            return url.path
        }
        return urlComponents.dropFirst(rootComponents.count).joined(separator: "/")
    }

    // MARK: System folders + legacy migration

    nonisolated func ensureSystemFolders() throws {
        if !FileManager.default.fileExists(atPath: root.path) {
            try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        }
        try migrateLegacyFolders()

        for name in NotesLayout.requiredSystemFolders {
            let url = root.appendingPathComponent(name)
            if !FileManager.default.fileExists(atPath: url.path) {
                try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
            }
        }

        var order = readOrder(at: root)
        var changed = false
        for name in NotesLayout.visibleSystemFolders where !order.folderOrder.contains(name) {
            order.folderOrder.append(name)
            changed = true
        }
        if changed { try writeOrder(order, at: root) }

        // Feed never keeps an order file.
        let feedOrder = root
            .appendingPathComponent(NotesLayout.feedFolder)
            .appendingPathComponent(NotesLayout.orderFileName)
        if FileManager.default.fileExists(atPath: feedOrder.path) {
            try? FileManager.default.removeItem(at: feedOrder)
        }
    }

    nonisolated private func migrateLegacyFolders() throws {
        try mergeFolder(from: NotesLayout.legacyUnsortedFolder, into: NotesLayout.feedFolder)
        try mergeFolder(from: NotesLayout.legacyRecordingsFolder, into: NotesLayout.recordingsFolder)
    }

    nonisolated private func mergeFolder(from fromName: String, into toName: String) throws {
        let from = root.appendingPathComponent(fromName)
        guard FileManager.default.fileExists(atPath: from.path) else { return }
        let to = root.appendingPathComponent(toName)
        if !FileManager.default.fileExists(atPath: to.path) {
            try FileManager.default.moveItem(at: from, to: to)
            return
        }
        let entries = (try? FileManager.default.contentsOfDirectory(at: from, includingPropertiesForKeys: nil)) ?? []
        for entry in entries {
            let target = to.appendingPathComponent(entry.lastPathComponent)
            if FileManager.default.fileExists(atPath: target.path) { continue }
            try FileManager.default.moveItem(at: entry, to: target)
        }
        try? FileManager.default.removeItem(at: from)
    }

    // MARK: Tree

    nonisolated func buildTree() throws -> FolderTree {
        try buildNode(at: root, relative: "")
    }

    nonisolated private func buildNode(at dir: URL, relative rel: String) throws -> FolderTree {
        let order = readOrder(at: dir)
        var folderNames: [String] = []
        var noteNames: [String] = []

        let entries = try FileManager.default.contentsOfDirectory(
            at: dir,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: []
        )
        for entry in entries {
            let name = entry.lastPathComponent
            if name == NotesLayout.orderFileName { continue }
            if rel.isEmpty && NotesLayout.hiddenRootFolders.contains(name) { continue }
            let isDir = (try? entry.resourceValues(forKeys: [.isDirectoryKey]))?.isDirectory ?? false
            if isDir {
                if name.hasPrefix(".") { continue }
                folderNames.append(name)
            } else if entry.pathExtension == "md" {
                noteNames.append(name)
            }
        }

        let sortedFolders = OrderFile.sort(folderNames, by: order.folderOrder)
        let sortedNotes: [String]
        if rel == NotesLayout.feedFolder {
            // Feed: newest-first by filename (timestamp-prefixed). The UI re-sorts
            // by real front-matter timestamps once previews load.
            sortedNotes = noteNames.sorted { $0.lowercased() > $1.lowercased() }
        } else {
            sortedNotes = OrderFile.sort(noteNames, by: order.noteOrder)
        }

        var children: [FolderTree] = []
        for name in sortedFolders {
            let childRel = rel.isEmpty ? name : "\(rel)/\(name)"
            children.append(try buildNode(at: dir.appendingPathComponent(name), relative: childRel))
        }

        let notes = sortedNotes.map { name -> NoteRef in
            let noteRel = rel.isEmpty ? name : "\(rel)/\(name)"
            return NoteRef(name: name, path: noteRel)
        }

        return FolderTree(
            name: rel.isEmpty ? "Notes" : dir.lastPathComponent,
            path: rel,
            folders: children,
            notes: notes
        )
    }

    // MARK: Read / write

    nonisolated func readDocument(relativePath: String) throws -> NoteDocument {
        let url = url(forRelative: relativePath)
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw NotesStoreError.notFound(relativePath)
        }
        let raw = try String(contentsOf: url, encoding: .utf8)
        return NoteDocument.parse(raw)
    }

    nonisolated func writeDocument(_ doc: NoteDocument, relativePath: String) throws {
        let url = url(forRelative: relativePath)
        try FileManager.default.createDirectory(
            at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try Data(doc.render().utf8).write(to: url, options: .atomic)
    }

    /// Update an existing note's body, refreshing `updated_ms`. Preserves all
    /// other front-matter (and passthrough lines).
    nonisolated func writeBody(_ body: String, relativePath: String, now: Int64? = nil) throws {
        var doc =
            (try? readDocument(relativePath: relativePath))
            ?? NoteDocument(frontMatter: NoteFrontMatter(), body: "")
        if doc.frontMatter.id == nil { doc.frontMatter.id = UUIDv7.generate() }
        let nowMs = now ?? Int64(Date().timeIntervalSince1970 * 1000)
        if doc.frontMatter.createdMs == nil { doc.frontMatter.createdMs = nowMs }
        doc.frontMatter.updatedMs = nowMs
        doc.body = body
        try writeDocument(doc, relativePath: relativePath)
    }

    // MARK: Create

    /// Create a note in `folderRelative` (default Feed). Returns its relative path.
    @discardableResult
    nonisolated func createNote(
        folderRelative: String,
        content: String,
        timestampMs: Int64? = nil,
        format: NoteFileNameFormat
    ) throws -> String {
        let folderRel = folderRelative.isEmpty ? NotesLayout.feedFolder : folderRelative
        let folderURL = url(forRelative: folderRel)
        try FileManager.default.createDirectory(at: folderURL, withIntermediateDirectories: true)

        let now = timestampMs ?? Int64(Date().timeIntervalSince1970 * 1000)
        let noteId = UUIDv7.generate(now: now)
        let fallback = "note"
        let fileName = NoteNaming.allocateFileName(
            format: format,
            timestampMs: now,
            noteId: noteId,
            content: content,
            fallbackSlug: fallback
        ) { candidate in
            FileManager.default.fileExists(atPath: folderURL.appendingPathComponent(candidate).path)
        }

        var fm = NoteFrontMatter()
        fm.id = noteId
        fm.createdMs = now
        fm.updatedMs = now
        let doc = NoteDocument(frontMatter: fm, body: content)

        let rel = "\(folderRel)/\(fileName)"
        try writeDocument(doc, relativePath: rel)
        if folderRel != NotesLayout.feedFolder {
            try appendOrder(names: [fileName], isFolder: false, at: folderURL)
        }
        return rel
    }

    /// Create a subfolder. Returns its relative path.
    @discardableResult
    nonisolated func createFolder(parentRelative: String, name: String) throws -> String {
        let cleanName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanName.isEmpty, !cleanName.contains("/"), !cleanName.hasPrefix(".") else {
            throw NotesStoreError.invalidName(name)
        }
        let parentURL = url(forRelative: parentRelative)
        let folderURL = parentURL.appendingPathComponent(cleanName)
        try FileManager.default.createDirectory(at: folderURL, withIntermediateDirectories: true)
        if parentRelative != NotesLayout.feedFolder {
            try appendOrder(names: [cleanName], isFolder: true, at: parentURL)
        }
        return parentRelative.isEmpty ? cleanName : "\(parentRelative)/\(cleanName)"
    }

    // MARK: Delete

    nonisolated func delete(relativePaths: [String]) throws {
        for rel in relativePaths {
            let url = url(forRelative: rel)
            let name = url.lastPathComponent
            if NotesLayout.protectedFolders.contains(rel) {
                throw NotesStoreError.protectedFolder(name)
            }
            guard FileManager.default.fileExists(atPath: url.path) else { continue }
            try FileManager.default.removeItem(at: url)
            let parent = url.deletingLastPathComponent()
            if parent != root.appendingPathComponent(NotesLayout.feedFolder) {
                try? removeOrder(names: [name], at: parent)
            }
        }
    }

    // MARK: Previews

    /// Build previews for every note directly inside `folderRelative`, sorted the
    /// way the UI wants: Feed is newest-first by date, other folders follow the
    /// order file (already applied by `buildTree`).
    nonisolated func previews(inFolderRelative folderRel: String, treeNotes: [NoteRef]) -> [NotePreview] {
        var previews: [NotePreview] = []
        previews.reserveCapacity(treeNotes.count)
        for ref in treeNotes {
            guard let doc = try? readDocument(relativePath: ref.path) else { continue }
            previews.append(NotePreview.make(from: doc, path: ref.path))
        }
        if folderRel == NotesLayout.feedFolder {
            previews.sort { $0.sortKey > $1.sortKey }
        }
        return previews
    }

    // MARK: Order files

    nonisolated func readOrder(at dir: URL) -> OrderFile {
        let url = dir.appendingPathComponent(NotesLayout.orderFileName)
        guard let data = try? Data(contentsOf: url),
            let order = try? JSONDecoder().decode(OrderFile.self, from: data)
        else { return OrderFile() }
        return order
    }

    nonisolated func writeOrder(_ order: OrderFile, at dir: URL) throws {
        // Feed sorts by date and never persists an order file (matches Rust).
        if dir.lastPathComponent == NotesLayout.feedFolder { return }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted]
        let data = try encoder.encode(order)
        try data.write(to: dir.appendingPathComponent(NotesLayout.orderFileName), options: .atomic)
    }

    nonisolated func appendOrder(names: [String], isFolder: Bool, at dir: URL) throws {
        var order = readOrder(at: dir)
        for name in names {
            if isFolder {
                if !order.folderOrder.contains(name) { order.folderOrder.append(name) }
            } else {
                if !order.noteOrder.contains(name) { order.noteOrder.append(name) }
            }
        }
        try writeOrder(order, at: dir)
    }

    nonisolated func removeOrder(names: [String], at dir: URL) throws {
        var order = readOrder(at: dir)
        order.folderOrder.removeAll { names.contains($0) }
        order.noteOrder.removeAll { names.contains($0) }
        try writeOrder(order, at: dir)
    }

    // MARK: Recordings (Stage 3)

    /// Allocate a unique audio file inside `Recordings/` (port of
    /// `recording_audio_file_path`). Returns the absolute URL and the root-relative
    /// path to store in front-matter.
    nonisolated func allocateAudioFile(extension ext: String) throws -> (url: URL, relativePath: String) {
        let storage = root.appendingPathComponent(NotesLayout.recordingsFolder)
        try FileManager.default.createDirectory(at: storage, withIntermediateDirectories: true)
        for _ in 0...512 {
            let name = "audio-\(UUIDv7.generate()).\(ext)"
            let url = storage.appendingPathComponent(name)
            if !FileManager.default.fileExists(atPath: url.path) {
                return (url, "\(NotesLayout.recordingsFolder)/\(name)")
            }
        }
        throw NotesStoreError.invalidName("audio file")
    }

    /// Create a recording note referencing an already-written audio file, in the
    /// exact shape the desktop writes (port of `RecordingsGateway::save`):
    /// `type: audio_recording`, `recording_audio_path`, `transcription_status:
    /// pending`, empty body. Returns the note's relative path.
    @discardableResult
    nonisolated func createRecordingNote(
        folderRelative: String,
        audioRelativePath: String,
        timestampMs: Int64? = nil,
        format: NoteFileNameFormat
    ) throws -> String {
        let folderRel = folderRelative.isEmpty ? NotesLayout.feedFolder : folderRelative
        let folderURL = url(forRelative: folderRel)
        try FileManager.default.createDirectory(at: folderURL, withIntermediateDirectories: true)

        let now = timestampMs ?? Int64(Date().timeIntervalSince1970 * 1000)
        let noteId = UUIDv7.generate(now: now)
        let fallback = "recording-\(NoteNaming.uuidTailWithoutTimestampPrefix(noteId))"
        let fileName = NoteNaming.allocateFileName(
            format: format, timestampMs: now, noteId: noteId,
            content: "", fallbackSlug: fallback
        ) { candidate in
            FileManager.default.fileExists(atPath: folderURL.appendingPathComponent(candidate).path)
        }

        var fm = NoteFrontMatter()
        fm.id = noteId
        fm.createdMs = now
        fm.updatedMs = now
        fm.type = kRecordingNoteType
        fm.recordingAudioPath = audioRelativePath
        fm.transcriptionStatus = TranscriptionStatus.pending
        fm.transcriptionUpdatedMs = now

        let rel = "\(folderRel)/\(fileName)"
        try writeDocument(NoteDocument(frontMatter: fm, body: ""), relativePath: rel)
        if folderRel != NotesLayout.feedFolder {
            try appendOrder(names: [fileName], isFolder: false, at: folderURL)
        }
        return rel
    }
}

//
//  Workspace.swift
//  Type
//
//  A "workspace" is the working directory the app reads/writes/syncs — the same
//  concept the desktop calls a *profile*. Today the app ships a single default
//  workspace, but the model is intentionally a list with per-workspace settings
//  so multi-profile support (item 7 in the brief) can be added later without a
//  data migration: each workspace already owns its own notes root and its own
//  git remote / settings.
//

import Foundation

/// Per-workspace settings. Anything that can legitimately differ between two
/// working directories lives here (git remote, filename strategy, …).
struct WorkspaceSettings: Codable, Equatable {
    var noteFileNameFormat: NoteFileNameFormat = .utcTimestampSlug

    // Git sync (Stage 2). The secret (token / password) is NOT stored here — it
    // lives in the Keychain keyed by the workspace id.
    var gitRemoteURL: String = ""
    /// Empty means "use whatever branch HEAD points at, else main".
    var gitBranch: String = ""
    var gitUsername: String = ""
    var gitAuthorName: String = ""
    var gitAuthorEmail: String = ""

    // Transcription (Stage 4). Off by default — phone is record-first; review and
    // organize on the desktop after sync, or enable on-device transcription here.
    var transcriptionEnabled: Bool = false
}

struct Workspace: Codable, Identifiable, Equatable {
    var id: String
    var name: String
    /// Notes-root path relative to the app's Documents directory (e.g. "Notes").
    /// Keeping it relative keeps the data portable and visible in the Files app.
    var relativeRoot: String
    var settings: WorkspaceSettings

    init(
        id: String = UUIDv7.generate(),
        name: String,
        relativeRoot: String,
        settings: WorkspaceSettings = WorkspaceSettings()
    ) {
        self.id = id
        self.name = name
        self.relativeRoot = relativeRoot
        self.settings = settings
    }

    static let defaultWorkspace = Workspace(name: "Notes", relativeRoot: "Notes")
}

/// On-disk shape of the workspaces config (stored in Application Support, NOT in
/// any notes root, so it never syncs through git). Maps cleanly onto the desktop
/// `.notes-profiles.json` if the two are ever unified.
struct WorkspacesConfig: Codable, Equatable {
    var activeWorkspaceId: String
    var workspaces: [Workspace]
}

//
//  Constants.swift
//  Type
//
//  On-disk + app-wide constants. The notes layout constants MUST stay in sync
//  with the Tauri/Rust backend (`src-tauri/src/adapters/notes/mod.rs` and
//  `src-tauri/src/lib.rs`) so the same git repo round-trips between desktop and
//  iOS without either side corrupting the other's data.
//

import Foundation

enum AppConstants {
    /// Custom URL scheme used by the home-screen widget deep link (`type://record`).
    /// Declared in the app target's Info settings (`CFBundleURLTypes`).
    static let urlScheme = "type"

    /// App Group shared between the app and the widget / Live Activity extension.
    /// You MUST enable this App Group capability on BOTH the `Type` and
    /// `Type Record WidgetExtension` targets in Signing & Capabilities.
    static let appGroupIdentifier = "group.com.digital.Type"
}

/// Folder + file conventions. Mirror of the Rust backend constants. Do not change
/// the spellings — in particular the "Archieve" misspelling is intentional and
/// persisted in real user data.
enum NotesLayout {
    static let feedFolder = "Feed"
    /// Intentional misspelling — matches persisted desktop data. Do NOT "fix" it.
    static let archiveFolder = "Archieve"
    static let recordingsFolder = "Recordings"
    static let attachmentsFolder = "Attachments"
    static let legacyUnsortedFolder = "Unsorted"
    static let legacyRecordingsFolder = "_Recordings"
    static let orderFileName = ".notes-order.json"

    /// Hidden from the tree when they appear at the root level (storage-only).
    static let hiddenRootFolders: Set<String> = [
        recordingsFolder, attachmentsFolder, legacyRecordingsFolder,
    ]

    /// Always exist; cannot be renamed or deleted by the user.
    static let protectedFolders: Set<String> = [
        feedFolder, archiveFolder, legacyUnsortedFolder,
        attachmentsFolder, recordingsFolder, legacyRecordingsFolder,
    ]

    /// Created on first run and shown in the folder tree.
    static let visibleSystemFolders = [feedFolder, archiveFolder]

    /// Created on first run (includes hidden storage folders).
    static let requiredSystemFolders = [
        feedFolder, archiveFolder, attachmentsFolder, recordingsFolder,
    ]
}

/// Transcription status values written to front-matter `transcription_status`.
/// Mirror of the Rust `RECORDING_STATUS_*` constants.
enum TranscriptionStatus {
    static let pending = "pending"
    static let queued = "queued"
    static let processing = "processing"
    static let completed = "completed"
    static let failed = "failed"
}

/// front-matter `type` value for recording notes (Rust `RECORDING_FRONTMATTER_TYPE`).
let kRecordingNoteType = "audio_recording"

//
//  AudioRecorder.swift
//  Type   (app target only)
//
//  The one place audio is captured. Recording ALWAYS happens here, in the app
//  process, because only the app owns the `AVAudioSession` and the `audio`
//  background mode that keeps capture alive on the lock screen — a widget
//  extension can't reliably hold the mic.
//
//  Two ways recording gets driven:
//   1. In-app UI (RecordingView) and the home-screen widget deep link
//      (`type://record`) call `start()/stop()` directly on this singleton.
//   2. Lock-screen surfaces (Live Activity buttons, Control widget) can't reach
//      this object across the process boundary, so they post a `RecordingBridge`
//      command + Darwin poke; we observe that here and react. This is how a
//      recording is paused/stopped from the lock screen WITHOUT unlocking — the
//      app is already alive in the background holding the audio session, exactly
//      like the system Voice Memos app.
//
//  On stop, a recording note is written in the desktop's exact `audio_recording`
//  front-matter shape (see `NotesStore.createRecordingNote`) so it round-trips
//  through the same git repo.
//

import AVFoundation
import ActivityKit
import Foundation
import Observation
import WidgetKit

@MainActor
@Observable
final class AudioRecorder: NSObject {
    static let shared = AudioRecorder()

    enum State: Equatable { case idle, recording, paused }

    private(set) var state: State = .idle
    /// Origin for the elapsed-time clock (already adjusted for paused gaps).
    private(set) var timerOrigin: Date?
    private(set) var lastError: String?

    /// Set by `AppState` so the new note is opened + the tree refreshed.
    var onSaved: ((String) -> Void)?

    // Configured by AppState (recording runs in-app, so we read the live root
    // directly rather than through the App Group).
    private var notesRoot: URL?
    private var fileNameFormat: NoteFileNameFormat = .utcTimestampSlug
    private var targetFolder = NotesLayout.feedFolder
    private var workspaceName = "Type"

    private var recorder: AVAudioRecorder?
    private var currentAudioRelative: String?
    private var accumulated: TimeInterval = 0
    private var segmentStart: Date?
    private var activity: Activity<RecordingActivityAttributes>?
    private var observerInstalled = false

    var isRecording: Bool { state != .idle }

    // MARK: Configuration

    /// Point the recorder at the active workspace. Safe to call repeatedly; it
    /// also installs the cross-process command observer on first call.
    func configure(
        root: URL, format: NoteFileNameFormat, folder: String, workspaceName: String
    ) {
        self.notesRoot = root
        self.fileNameFormat = format
        self.targetFolder = folder.isEmpty ? NotesLayout.feedFolder : folder
        self.workspaceName = workspaceName
        installBridgeObserverIfNeeded()
    }

    func setTargetFolder(_ folder: String) {
        targetFolder = folder.isEmpty ? NotesLayout.feedFolder : folder
    }

    // MARK: Public controls

    func toggleFromUI() {
        switch state {
        case .idle: start()
        case .recording, .paused: stopAndSave()
        }
    }

    func start() {
        guard state == .idle else { return }
        guard let root = notesRoot else {
            lastError = "No workspace configured."
            return
        }
        requestPermission { [weak self] granted in
            guard let self else { return }
            guard granted else {
                self.lastError = "Microphone access denied."
                return
            }
            self.beginCapture(root: root)
        }
    }

    func pause() {
        guard state == .recording, let recorder else { return }
        recorder.pause()
        if let segmentStart { accumulated += Date().timeIntervalSince(segmentStart) }
        segmentStart = nil
        state = .paused
        publishState()
        updateActivity()
    }

    func resume() {
        guard state == .paused, let recorder else { return }
        recorder.record()
        segmentStart = Date()
        timerOrigin = Date().addingTimeInterval(-accumulated)
        state = .recording
        publishState()
        updateActivity()
    }

    func toggle() {
        switch state {
        case .recording: pause()
        case .paused: resume()
        case .idle: start()
        }
    }

    /// Stop, write the recording note, and notify.
    func stopAndSave() {
        guard state != .idle, let recorder, let root = notesRoot,
            let audioRelative = currentAudioRelative
        else {
            resetToIdle(endActivity: true)
            return
        }
        recorder.stop()
        self.recorder = nil

        let store = NotesStore(root: root)
        do {
            let notePath = try store.createRecordingNote(
                folderRelative: targetFolder,
                audioRelativePath: audioRelative,
                format: fileNameFormat
            )
            onSaved?(notePath)
        } catch {
            lastError = error.localizedDescription
        }
        resetToIdle(endActivity: true)
    }

    /// Stop and discard the audio (no note written).
    func cancel() {
        if let recorder {
            let url = recorder.url
            recorder.stop()
            try? FileManager.default.removeItem(at: url)
        }
        recorder = nil
        currentAudioRelative = nil
        resetToIdle(endActivity: true)
    }

    // MARK: Capture internals

    private func beginCapture(root: URL) {
        do {
            try configureSession()
            let store = NotesStore(root: root)
            let (url, relative) = try store.allocateAudioFile(extension: "m4a")
            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue,
            ]
            let recorder = try AVAudioRecorder(url: url, settings: settings)
            recorder.delegate = self
            guard recorder.record() else {
                lastError = "Failed to start recording."
                try? FileManager.default.removeItem(at: url)
                return
            }
            self.recorder = recorder
            self.currentAudioRelative = relative
            self.accumulated = 0
            self.segmentStart = Date()
            self.timerOrigin = Date()
            self.state = .recording
            self.lastError = nil
            publishState()
            startActivity()
        } catch {
            lastError = error.localizedDescription
        }
    }

    private func configureSession() throws {
        let session = AVAudioSession.sharedInstance()
        try session.setCategory(
            .playAndRecord, mode: .default,
            options: [.allowBluetooth, .defaultToSpeaker, .duckOthers])
        try session.setActive(true, options: [])
    }

    private func requestPermission(_ completion: @escaping (Bool) -> Void) {
        AVAudioApplication.requestRecordPermission { granted in
            Task { @MainActor in completion(granted) }
        }
    }

    private func resetToIdle(endActivity: Bool) {
        state = .idle
        timerOrigin = nil
        segmentStart = nil
        accumulated = 0
        currentAudioRelative = nil
        if endActivity { self.endActivity() }
        publishState()
        try? AVAudioSession.sharedInstance().setActive(false, options: [.notifyOthersOnDeactivation])
    }

    // MARK: Cross-process command bridge

    private func installBridgeObserverIfNeeded() {
        guard !observerInstalled else { return }
        observerInstalled = true
        let center = CFNotificationCenterGetDarwinNotifyCenter()
        CFNotificationCenterAddObserver(
            center,
            Unmanaged.passUnretained(self).toOpaque(),
            { _, _, _, _, _ in
                // C callback: no captures allowed. Hop to the main actor and read
                // the queued command from the shared App Group.
                Task { @MainActor in AudioRecorder.shared.handleBridgeCommand() }
            },
            RecordingSignal.command.name as CFString,
            nil,
            .deliverImmediately)
    }

    /// Drain whatever command a widget surface queued.
    func handleBridgeCommand() {
        guard let pending = RecordingBridge.takeCommand() else { return }
        if let folder = pending.folder, !folder.isEmpty { setTargetFolder(folder) }
        switch pending.command {
        case .start: start()
        case .stop: stopAndSave()
        case .toggle: toggle()
        case .cancel: cancel()
        }
    }

    private func publishState() {
        RecordingBridge.publish(
            RecordingPublishedState(
                isRecording: isRecording,
                isPaused: state == .paused,
                startedAt: timerOrigin),
            workspaceName: workspaceName)
        WidgetCenter.shared.reloadAllTimelines()
    }

    // MARK: Live Activity (lock-screen surface)

    private func startActivity() {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else { return }
        let attributes = RecordingActivityAttributes(workspaceName: workspaceName)
        let content = ActivityContent(
            state: .init(startedAt: timerOrigin ?? Date(), isPaused: false),
            staleDate: nil)
        activity = try? Activity.request(
            attributes: attributes, content: content, pushType: nil)
    }

    private func updateActivity() {
        guard let activity else { return }
        let content = ActivityContent(
            state: .init(startedAt: timerOrigin ?? Date(), isPaused: state == .paused),
            staleDate: nil)
        Task { await activity.update(content) }
    }

    private func endActivity() {
        guard let activity else { return }
        let final = ActivityContent(
            state: .init(startedAt: timerOrigin ?? Date(), isPaused: true),
            staleDate: nil)
        Task { await activity.end(final, dismissalPolicy: .immediate) }
        self.activity = nil
    }
}

extension AudioRecorder: AVAudioRecorderDelegate {
    nonisolated func audioRecorderDidFinishRecording(
        _ recorder: AVAudioRecorder, successfully flag: Bool
    ) {
        // Interruptions (e.g. a phone call) finish the recorder out from under us.
        Task { @MainActor in
            if AudioRecorder.shared.state != .idle && !flag {
                AudioRecorder.shared.lastError = "Recording was interrupted."
            }
        }
    }
}

