167	}
168	
169	/// Zeroize the old key before replacing it.
170	fn reset_runtime_key(state: &mut SecurityRuntimeState, next_key: Option<[u8; SECURITY_KEY_SIZE]>) {
171	    if let Some(mut existing) = state.key.take() {
172	        existing.zeroize();
173	    }
174	    state.key = next_key;
175	}
176	
177	fn read_security_config(app: &tauri::AppHandle) -> Result<SecurityConfigFile, String> {
178	    let path = security_file_path(app)?;
179	    if !path.exists() {
180	        return Ok(SecurityConfigFile::default());
181	    }
182	    let raw = fs::read_to_string(&path).map_err(|err| err.to_string())?;
183	    let parsed = serde_json::from_str::<SecurityConfigFile>(&raw)
184	        .unwrap_or_else(|_| SecurityConfigFile::default());
185	    Ok(parsed)
186	}
187	
188	fn write_security_config(
189	    app: &tauri::AppHandle,
190	    config: &SecurityConfigFile,
191	) -> Result<(), String> {
192	    let path = security_file_path(app)?;
193	    let raw = serde_json::to_string_pretty(config).map_err(|err| err.to_string())?;
194	    fs::write(path, raw).map_err(|err| err.to_string())
195	}
196	
197	fn ensure_security_runtime_loaded(app: &tauri::AppHandle) -> Result<(), String> {
198	    let runtime = security_runtime_state();
199	    let mut state = runtime
200	        .lock()
201	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
202	    if state.loaded {
203	        return Ok(());
204	    }
205	    let config = read_security_config(app)?;
206	    state.config = config.clone();
207	    state.loaded = true;
208	    state.locked = config.encryption_enabled;
209	    reset_runtime_key(&mut state, None);
210	    Ok(())
211	}
212	
213	fn security_state_snapshot(app: &tauri::AppHandle) -> Result<SecurityState, String> {
214	    ensure_security_runtime_loaded(app)?;
215	    let runtime = security_runtime_state();
216	    let state = runtime
217	        .lock()
218	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
219	    Ok(SecurityState {
220	        encryption_enabled: state.config.encryption_enabled,
221	        locked: state.config.encryption_enabled && state.locked,
222	        auto_lock_on_background: state.config.auto_lock_on_background,
223	    })
224	}
