226	// ── Password / key derivation ──────────────────────────────────────────────────
227	
228	fn security_password_hash(value: &str) -> Result<String, String> {
229	    let salt = SaltString::generate(&mut OsRng);
230	    Argon2::default()
231	        .hash_password(value.as_bytes(), &salt)
232	        .map(|hash| hash.to_string())
233	        .map_err(|error| error.to_string())
234	}
235	
236	fn security_password_matches(value: &str, hash: &str) -> Result<bool, String> {
237	    if hash.trim().is_empty() {
238	        return Ok(false);
239	    }
240	    let parsed = PasswordHash::new(hash).map_err(|error| error.to_string())?;
241	    Ok(Argon2::default()
242	        .verify_password(value.as_bytes(), &parsed)
243	        .is_ok())
244	}
245	
246	fn decode_security_key_salt(config: &SecurityConfigFile) -> Result<Vec<u8>, String> {
247	    let trimmed = config.key_salt.trim();
248	    if trimmed.is_empty() {
249	        return Err("Security key salt is not configured.".to_string());
250	    }
251	    BASE64.decode(trimmed).map_err(|error| error.to_string())
252	}
253	
254	fn derive_security_key(password: &str, salt: &[u8]) -> Result<[u8; SECURITY_KEY_SIZE], String> {
255	    let mut key = [0u8; SECURITY_KEY_SIZE];
256	    Argon2::default()
257	        .hash_password_into(password.as_bytes(), salt, &mut key)
258	        .map_err(|error| error.to_string())?;
259	    Ok(key)
260	}
261	
262	// ── Note body encryption / decryption ──────────────────────────────────────────
263	
264	fn is_encrypted_note_body(body: &str) -> bool {
265	    body.trim_start().starts_with(SECURITY_NOTE_BODY_PREFIX)
266	}
267	
268	fn encrypt_note_body_with_key(body: &str, key: &[u8; SECURITY_KEY_SIZE]) -> Result<String, String> {
269	    if is_encrypted_note_body(body) {
270	        return Ok(body.to_string());
271	    }
272	    let cipher = XChaCha20Poly1305::new(Key::from_slice(key));
273	    let mut nonce_bytes = [0u8; SECURITY_NONCE_SIZE];
274	    OsRng.fill_bytes(&mut nonce_bytes);
275	    let ciphertext = cipher
276	        .encrypt(XNonce::from_slice(&nonce_bytes), body.as_bytes())
277	        .map_err(|error| error.to_string())?;
278	    let mut payload = Vec::with_capacity(SECURITY_NONCE_SIZE + ciphertext.len());
279	    payload.extend_from_slice(&nonce_bytes);
280	    payload.extend_from_slice(&ciphertext);
281	    Ok(format!(
282	        "{}{}",
283	        SECURITY_NOTE_BODY_PREFIX,
284	        BASE64.encode(payload)
285	    ))
286	}
287	
288	fn decrypt_note_body_with_key(body: &str, key: &[u8; SECURITY_KEY_SIZE]) -> Result<String, String> {
289	    if !is_encrypted_note_body(body) {
290	        return Ok(body.to_string());
291	    }
292	    let encoded = body
293	        .trim_start()
294	        .trim()
295	        .strip_prefix(SECURITY_NOTE_BODY_PREFIX)
296	        .ok_or_else(|| "Invalid encrypted note marker.".to_string())?;
297	    let payload = BASE64.decode(encoded).map_err(|error| error.to_string())?;
298	    if payload.len() <= SECURITY_NONCE_SIZE {
299	        return Err("Encrypted note payload is invalid.".to_string());
300	    }
301	    let (nonce_bytes, ciphertext) = payload.split_at(SECURITY_NONCE_SIZE);
302	    let cipher = XChaCha20Poly1305::new(Key::from_slice(key));
303	    let decrypted = cipher
304	        .decrypt(XNonce::from_slice(nonce_bytes), ciphertext)
305	        .map_err(|_| "Failed to decrypt note. Wrong password or corrupted content.".to_string())?;
306	    String::from_utf8(decrypted).map_err(|error| error.to_string())
307	}
308	
309	/// Decrypt an encrypted note body using the runtime key (returns as-is if not encrypted).
310	pub(crate) fn decrypt_note_body_for_read(body: &str) -> Result<String, String> {
311	    if !is_encrypted_note_body(body) {
312	        return Ok(body.to_string());
313	    }
314	    let runtime = security_runtime_state();
315	    let state = runtime
316	        .lock()
317	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
318	    let key = state
319	        .key
320	        .as_ref()
321	        .ok_or_else(|| SECURITY_LOCKED_ERROR.to_string())?;
322	    decrypt_note_body_with_key(body, key)
323	}
324	
325	/// Encrypt a note body for writing (no-op if encryption is disabled).
326	pub(crate) fn encrypt_note_body_for_write(body: &str) -> Result<String, String> {
327	    let runtime = security_runtime_state();
328	    let state = runtime
329	        .lock()
330	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
331	    if !state.config.encryption_enabled {
332	        return Ok(body.to_string());
333	    }
334	    let key = state
335	        .key
336	        .as_ref()
337	        .ok_or_else(|| SECURITY_LOCKED_ERROR.to_string())?;
338	    encrypt_note_body_with_key(body, key)
339	}
340	
341	// ── Lock gate ──────────────────────────────────────────────────────────────────
342	
343	/// Reject operations when the app is locked.
344	pub(crate) fn ensure_security_unlocked_for_app(app: &tauri::AppHandle) -> Result<(), String> {
345	    ensure_security_runtime_loaded(app)?;
346	    let runtime = security_runtime_state();
347	    let state = runtime
348	        .lock()
349	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
350	    if state.config.encryption_enabled && state.locked {
351	        return Err(SECURITY_LOCKED_ERROR.to_string());
352	    }
353	    Ok(())
354	}
355	
356	// ── Migration helpers ──────────────────────────────────────────────────────────
357	
358	/// Collect unique notes roots across all profiles.
359	fn collect_profile_roots(state: &NotesProfilesFile) -> Vec<PathBuf> {
360	    let mut seen = HashSet::new();
361	    let mut roots = Vec::new();
362	    for profile in &state.profiles {
363	        let path = PathBuf::from(profile.notes_root.trim());
364	        let key = path.to_string_lossy().to_string();
365	        if seen.insert(key) {
366	            roots.push(path);
367	        }
368	    }
369	    roots
370	}
371	
372	/// Encrypt all plaintext note bodies in a root directory.
373	fn migrate_root_note_bodies_to_encrypted(
374	    root: &Path,
375	    key: &[u8; SECURITY_KEY_SIZE],
376	) -> Result<(), String> {
377	    let mut note_files = Vec::new();
378	    collect_markdown_note_files(root, root, &mut note_files)?;
379	    for note_path in note_files {
380	        let raw = fs::read_to_string(&note_path).map_err(|error| error.to_string())?;
381	        let (meta, body) = parse_note_front_matter(&raw);
382	        let encrypted_body = encrypt_note_body_with_key(&body, key)?;
383	        let rendered = render_note_with_front_matter(&meta, &encrypted_body);
384	        fs::write(&note_path, rendered).map_err(|error| error.to_string())?;
385	    }
386	    Ok(())
387	}
388	
389	/// Seed a reset root with sample notes so the user has something to see.
390	fn seed_dummy_notes(root: &Path) -> Result<(), String> {
391	    let feed = root.join(FEED_FOLDER);
392	    fs::create_dir_all(&feed).map_err(|error| error.to_string())?;
393	    let now = now_ms().unwrap_or(0);
394	    let templates = [
395	        (
396	            "dummy-1-welcome.md",
397	            "Welcome back\n\nThis is a reset sample note.",
398	        ),
399	        (
400	            "dummy-2-local-sync.md",
401	            "Local sync\n\nUse a LAN/hotspot Git remote from Settings > Profile.",
402	        ),
403	        (
404	            "dummy-3-security.md",
405	            "Security reset\n\nYour app data was reset and this is a sample note.",
406	        ),
407	    ];
408	    for (index, (name, body)) in templates.iter().enumerate() {
409	        let path = feed.join(name);
410	        let mut meta = NoteFrontMatter::default();
411	        meta.id = Some(generate_note_id());
412	        meta.created_ms = Some(now + index as i64);
413	        meta.updated_ms = Some(now + index as i64);
414	        let rendered = render_note_with_front_matter(&meta, body);
415	        fs::write(path, rendered).map_err(|error| error.to_string())?;
416	    }
417	    Ok(())
418	}
419	
420	/// Panic-password triggered: wipe all profile data and reset to defaults.
421	fn panic_reset_local_data(app: &tauri::AppHandle) -> Result<(), String> {
422	    let state = ensure_profiles_state(app).or_else(|_| default_profiles_state(app))?;
423	    for root in collect_profile_roots(&state) {
424	        if root.exists() {
425	            fs::remove_dir_all(&root).map_err(|error| error.to_string())?;
426	        }
427	    }
428	
429	    if let Ok(path) = profiles_file_path(app) {
430	        if path.exists() {
431	            let _ = fs::remove_file(path);
432	        }
433	    }
434	    if let Ok(path) = legacy_profiles_file_path(app) {
435	        if path.exists() {
436	            let _ = fs::remove_file(path);
437	        }
438	    }
439	    if let Ok(path) = security_file_path(app) {
440	        if path.exists() {
441	            let _ = fs::remove_file(path);
442	        }
443	    }
444	    if let Ok(path) = app_data_dir(app).map(|dir| dir.join("native-recordings")) {
445	        if path.exists() {
446	            let _ = fs::remove_dir_all(path);
447	        }
448	    }
449	
450	    let next_state = default_profiles_state(app)?;
451	    write_profiles_state(app, &next_state)?;
452	    let active = find_profile(&next_state, &next_state.active_profile_id)
453	        .or_else(|| next_state.profiles.first())
454	        .ok_or_else(|| "No profiles configured.".to_string())?;
455	    let root = PathBuf::from(&active.notes_root);
456	    ensure_system_folders(&root)?;
457	    seed_dummy_notes(&root)?;
458	
459	    let runtime = security_runtime_state();
460	    let mut runtime_state = runtime
461	        .lock()
462	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
463	    runtime_state.loaded = true;
464	    runtime_state.config = SecurityConfigFile::default();
465	    runtime_state.locked = false;
466	    reset_runtime_key(&mut runtime_state, None);
467	    Ok(())
468	}
469	
470	// ── Public command implementations ─────────────────────────────────────────────
471	
472	/// Called during app setup to load security config from disk.
473	pub(crate) fn ensure_security_runtime_initialized_for_setup(
474	    app: &tauri::AppHandle,
475	) -> Result<(), String> {
476	    ensure_security_runtime_loaded(app)
477	}
478	
479	/// Return the current security state snapshot for the frontend.
480	pub(crate) fn get_security_state_impl(app: &tauri::AppHandle) -> Result<SecurityState, String> {
481	    security_state_snapshot(app)
482	}
483	
484	/// Enable encryption: hash passwords, derive key, encrypt all existing notes.
485	pub(crate) fn enable_security_impl(
486	    app: &tauri::AppHandle,
487	    args: EnableSecurityArgs,
488	) -> Result<SecurityState, String> {
489	    ensure_security_runtime_loaded(app)?;
490	    let unlock_password = args.unlock_password.trim();
491	    let panic_password = args.panic_password.trim();
492	    if unlock_password.is_empty() || panic_password.is_empty() {
493	        return Err("Unlock and panic passwords are required.".to_string());
494	    }
495	    if unlock_password == panic_password {
496	        return Err("Unlock and panic passwords must be different.".to_string());
497	    }
498	
499	    let mut salt_bytes = vec![0u8; SECURITY_SALT_SIZE];
500	    OsRng.fill_bytes(&mut salt_bytes);
501	    let key = derive_security_key(unlock_password, &salt_bytes)?;
502	    let unlock_hash = security_password_hash(unlock_password)?;
503	    let panic_hash = security_password_hash(panic_password)?;
504	
505	    let profiles_state = ensure_profiles_state(app).or_else(|_| default_profiles_state(app))?;
506	    for root in collect_profile_roots(&profiles_state) {
507	        if !root.exists() {
508	            continue;
509	        }
510	        migrate_root_note_bodies_to_encrypted(&root, &key)?;
511	    }
512	
513	    let config = SecurityConfigFile {
514	        encryption_enabled: true,
515	        unlock_password_hash: unlock_hash,
516	        panic_password_hash: panic_hash,
517	        key_salt: BASE64.encode(salt_bytes),
518	        auto_lock_on_background: true,
519	    };
520	    write_security_config(app, &config)?;
521	
522	    let runtime = security_runtime_state();
523	    let mut runtime_state = runtime
524	        .lock()
525	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
526	    runtime_state.loaded = true;
527	    runtime_state.config = config.clone();
528	    runtime_state.locked = false;
529	    reset_runtime_key(&mut runtime_state, Some(key));
530	
531	    Ok(SecurityState {
532	        encryption_enabled: true,
533	        locked: false,
534	        auto_lock_on_background: config.auto_lock_on_background,
535	    })
536	}
537	
538	/// Lock the app: zeroize the derived key from memory.
539	pub(crate) fn lock_security_impl(app: &tauri::AppHandle) -> Result<SecurityState, String> {
540	    ensure_security_runtime_loaded(app)?;
541	    let runtime = security_runtime_state();
542	    let mut state = runtime
543	        .lock()
544	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
545	    if !state.config.encryption_enabled {
546	        return Ok(SecurityState {
547	            encryption_enabled: false,
548	            locked: false,
549	            auto_lock_on_background: state.config.auto_lock_on_background,
550	        });
551	    }
552	    state.locked = true;
553	    reset_runtime_key(&mut state, None);
554	    Ok(SecurityState {
555	        encryption_enabled: true,
556	        locked: true,
557	        auto_lock_on_background: state.config.auto_lock_on_background,
558	    })
559	}
560	
561	/// Verify password; if panic password matches, wipe all data.
562	pub(crate) fn unlock_security_impl(
563	    app: &tauri::AppHandle,
564	    args: UnlockSecurityArgs,
565	) -> Result<SecurityUnlockResult, String> {
566	    ensure_security_runtime_loaded(app)?;
567	    let password = args.password.trim();
568	    if password.is_empty() {
569	        return Ok(SecurityUnlockResult {
570	            unlocked: false,
571	            panic_triggered: false,
572	            reset_required: false,
573	            message: Some("Password is required.".to_string()),
574	        });
575	    }
576	
577	    let runtime = security_runtime_state();
578	    let mut state = runtime
579	        .lock()
580	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
581	    if !state.config.encryption_enabled {
582	        state.locked = false;
583	        reset_runtime_key(&mut state, None);
584	        return Ok(SecurityUnlockResult {
585	            unlocked: true,
586	            panic_triggered: false,
587	            reset_required: false,
588	            message: None,
589	        });
590	    }
591	
592	    if security_password_matches(password, &state.config.panic_password_hash)? {
593	        drop(state);
594	        panic_reset_local_data(app)?;
595	        return Ok(SecurityUnlockResult {
596	            unlocked: true,
597	            panic_triggered: true,
598	            reset_required: true,
599	            message: None,
600	        });
601	    }
602	
603	    if !security_password_matches(password, &state.config.unlock_password_hash)? {
604	        return Ok(SecurityUnlockResult {
605	            unlocked: false,
606	            panic_triggered: false,
607	            reset_required: false,
608	            message: Some("Invalid password.".to_string()),
609	        });
610	    }
611	
612	    let salt = decode_security_key_salt(&state.config)?;
613	    let key = derive_security_key(password, &salt)?;
614	    state.locked = false;
615	    reset_runtime_key(&mut state, Some(key));
616	    Ok(SecurityUnlockResult {
617	        unlocked: true,
618	        panic_triggered: false,
619	        reset_required: false,
620	        message: None,
621	    })
622	}
623	
624	/// Update security preferences (e.g. auto-lock on background).
625	pub(crate) fn set_security_preferences_impl(
626	    app: &tauri::AppHandle,
627	    args: SetSecurityPreferencesArgs,
628	) -> Result<SecurityState, String> {
629	    ensure_security_runtime_loaded(app)?;
630	    let runtime = security_runtime_state();
631	    let mut state = runtime
632	        .lock()
633	        .map_err(|_| "Security runtime lock poisoned.".to_string())?;
634	    state.config.auto_lock_on_background = args.auto_lock_on_background;
635	    write_security_config(app, &state.config)?;
636	    Ok(SecurityState {
637	        encryption_enabled: state.config.encryption_enabled,
638	        locked: state.config.encryption_enabled && state.locked,
639	        auto_lock_on_background: state.config.auto_lock_on_background,
640	    })
641	}
